import React, { useState } from 'react';

const fieldRules = {
  schoolName:  v => v.trim().length > 1,
  schoolEmail: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()),
  schoolPhone: v => v.trim().length >= 7,
  country:     v => v !== '',
  province:    v => v !== '',
  city:        v => v !== '',
  address:     v => v.trim().length > 5,
  session:     v => v.trim().length > 2,
  accountNo:   v => v.trim().length > 3,
  iban:        v => v.trim().length > 5,
};

const errorMsgs = {
  schoolName: 'School name is required',
  schoolEmail: 'Enter a valid email address',
  schoolPhone: 'Enter a valid phone number',
  country: 'Please select a country',
  province: 'Please select a province',
  city: 'Please select a city',
  address: 'Please enter a complete address',
  session: 'Please enter the academic session',
  accountNo: 'Account number is required',
  iban: 'IBAN is required',
};

function FormInput({ icon, id, type = 'text', placeholder, value, onChange, onBlur, fieldErrors, required }) {
  const status = fieldErrors[id];
  return (
    <div className="input-wrapper">
      {icon && <i className={`fas ${icon} input-icon`}></i>}
      <input
        className={`form-input${icon ? ' has-icon' : ''}${status === 'error' ? ' error-field' : status === 'ok' ? ' success-field' : ''}`}
        id={id} type={type} placeholder={placeholder} value={value}
        onChange={e => onChange(id, e.target.value)}
        onBlur={e => onBlur && onBlur(id, e.target.value)}
      />
    </div>
  );
}

function FieldMsg({ id, fieldErrors }) {
  const status = fieldErrors[id];
  if (!status) return <span className="field-msg" />;
  if (status === 'ok') return <span className="field-msg success"><i className="fas fa-check-circle"></i> Looks good</span>;
  if (status === 'error') return <span className="field-msg error"><i className="fas fa-times-circle"></i> {errorMsgs[id]}</span>;
  return <span className="field-msg" />;
}

export default function SchoolTab({ schoolInfo, setSchoolInfo, onSave, onSaveDraft, markUnsaved, showToast }) {
  const [fieldErrors, setFieldErrors] = useState({});
  const [saving, setSaving] = useState(false);

  const handleChange = (id, val) => {
    setSchoolInfo(prev => ({ ...prev, [id]: val }));
    markUnsaved();
    if (fieldRules[id]) {
      setFieldErrors(prev => ({ ...prev, [id]: fieldRules[id](val) ? 'ok' : 'error' }));
    }
  };

  const handleBlur = (id, val) => {
    if (fieldRules[id]) {
      setFieldErrors(prev => ({ ...prev, [id]: fieldRules[id](val) ? 'ok' : (val ? 'error' : '') }));
    }
  };

  const validateAll = () => {
    const required = ['schoolName','schoolEmail','schoolPhone','country','province','city','address','session'];
    const missing = [];
    const errors = {};
    required.forEach(id => {
      const val = schoolInfo[id] || '';
      const ok = fieldRules[id] ? fieldRules[id](val) : !!val.trim();
      errors[id] = ok ? 'ok' : 'error';
      if (!ok) missing.push(errorMsgs[id] || id);
    });
    setFieldErrors(prev => ({ ...prev, ...errors }));
    return missing;
  };

  const handleSave = () => {
    const missing = validateAll();
    if (missing.length) { onSave('error', missing); return; }
    setSaving(true);
    setTimeout(() => {
      setSaving(false);
      onSave('success');
    }, 1200);
  };

  const handleDraft = () => {
    setSaving(true);
    setTimeout(() => { setSaving(false); onSaveDraft(); }, 1000);
  };

  const FG = ({ label, id, required: req, children, helper }) => (
    <div className="form-group">
      <label className="form-label" htmlFor={id}>
        {label} {req && <span className="req-star">*</span>}
      </label>
      {children}
      <FieldMsg id={id} fieldErrors={fieldErrors} />
      {helper && <span className="form-helper info"><i className="fas fa-info-circle"></i> {helper}</span>}
    </div>
  );

  return (
    <div className="tab-panel active" id="panelSchool">
      {/* Basic Info */}
      <div className="section-card">
        <div className="section-header">
          <div className="section-icon blue"><i className="fas fa-info-circle"></i></div>
          <div><div className="section-title">Basic School Information</div><div className="section-desc">Core identity details for your school</div></div>
        </div>
        <div className="form-grid form-grid-2" style={{ marginBottom: 16 }}>
          <FG label="School Name" id="schoolName" required>
            <FormInput icon="fa-school" id="schoolName" placeholder="e.g. Milford Sounds Academy" value={schoolInfo.schoolName} onChange={handleChange} onBlur={handleBlur} fieldErrors={fieldErrors} />
          </FG>
          <FG label="Registration Number" id="regNumber">
            <div className="input-wrapper">
              <i className="fas fa-id-card input-icon"></i>
              <input className="form-input has-icon" placeholder="e.g. REG-2024-001" value={schoolInfo.regNumber}
                onChange={e => handleChange('regNumber', e.target.value)} />
            </div>
          </FG>
          <FG label="School Email" id="schoolEmail" required>
            <FormInput icon="fa-envelope" id="schoolEmail" type="email" placeholder="school@example.com" value={schoolInfo.schoolEmail} onChange={handleChange} onBlur={handleBlur} fieldErrors={fieldErrors} />
          </FG>
          <FG label="Contact Number" id="schoolPhone" required>
            <FormInput icon="fa-phone" id="schoolPhone" type="tel" placeholder="+92 300 0000000" value={schoolInfo.schoolPhone} onChange={handleChange} onBlur={handleBlur} fieldErrors={fieldErrors} />
          </FG>
          <FG label="School Owner / Principal" id="ownerName">
            <div className="input-wrapper">
              <i className="fas fa-user-tie input-icon"></i>
              <input className="form-input has-icon" placeholder="Full name" value={schoolInfo.ownerName}
                onChange={e => handleChange('ownerName', e.target.value)} />
            </div>
          </FG>
          <FG label="Website URL" id="website">
            <div className="input-wrapper">
              <i className="fas fa-globe input-icon"></i>
              <input className="form-input has-icon" type="url" placeholder="https://yourschool.edu.pk" value={schoolInfo.website}
                onChange={e => handleChange('website', e.target.value)} />
            </div>
          </FG>
        </div>
        <div className="form-group">
          <label className="form-label">School Logo <span className="req-star">*</span></label>
          <div className="upload-zone" onClick={() => showToast('File picker would open here', 'info')}>
            <div className="upload-icon"><i className="fas fa-image"></i></div>
            <div className="upload-title">Upload School Logo</div>
            <div className="upload-sub">Drag & drop or <span>click to browse</span> — JPG, PNG (max 2MB)</div>
          </div>
        </div>
      </div>

      {/* Location */}
      <div className="section-card">
        <div className="section-header">
          <div className="section-icon green"><i className="fas fa-map-marked-alt"></i></div>
          <div><div className="section-title">Location Information</div><div className="section-desc">Where your school is located</div></div>
        </div>
        <div className="form-grid form-grid-3" style={{ marginBottom: 16 }}>
          <FG label="Country" id="country" required>
            <select className={`form-select${fieldErrors.country === 'error' ? ' error-field' : ''}`}
              value={schoolInfo.country} onChange={e => handleChange('country', e.target.value)}>
              <option value="">Select country</option>
              <option>Pakistan</option><option>India</option><option>Bangladesh</option>
            </select>
            <FieldMsg id="country" fieldErrors={fieldErrors} />
          </FG>
          <FG label="Province / State" id="province" required>
            <select className={`form-select${fieldErrors.province === 'error' ? ' error-field' : ''}`}
              value={schoolInfo.province} onChange={e => handleChange('province', e.target.value)}>
              <option value="">Select province</option>
              <option>Punjab</option><option>ICT (Islamabad)</option><option>Sindh</option><option>KPK</option><option>Balochistan</option>
            </select>
            <FieldMsg id="province" fieldErrors={fieldErrors} />
          </FG>
          <FG label="City" id="city" required>
            <select className={`form-select${fieldErrors.city === 'error' ? ' error-field' : ''}`}
              value={schoolInfo.city} onChange={e => handleChange('city', e.target.value)}>
              <option value="">Select city</option>
              <option>Islamabad</option><option>Lahore</option><option>Karachi</option><option>Rawalpindi</option><option>Faisalabad</option>
            </select>
            <FieldMsg id="city" fieldErrors={fieldErrors} />
          </FG>
        </div>
        <FG label="Complete Address" id="address" required>
          <textarea className={`form-input${fieldErrors.address === 'error' ? ' error-field' : fieldErrors.address === 'ok' ? ' success-field' : ''}`}
            rows={2} placeholder="Street address, area, city..." value={schoolInfo.address}
            onChange={e => handleChange('address', e.target.value)}
            onBlur={e => handleBlur('address', e.target.value)}
            style={{ resize: 'vertical', marginBottom: 0 }} />
          <FieldMsg id="address" fieldErrors={fieldErrors} />
        </FG>
        <div style={{ marginTop: 12 }}>
          <div className="form-grid form-grid-2">
            <FG label="Landmark" id="landmark">
              <input className="form-input" placeholder="Nearby landmark" value={schoolInfo.landmark}
                onChange={e => handleChange('landmark', e.target.value)} />
            </FG>
            <FG label="Academic Session" id="session" required>
              <input className={`form-input${fieldErrors.session === 'error' ? ' error-field' : fieldErrors.session === 'ok' ? ' success-field' : ''}`}
                placeholder="e.g. 2025-2026" value={schoolInfo.session}
                onChange={e => handleChange('session', e.target.value)}
                onBlur={e => handleBlur('session', e.target.value)} />
              <FieldMsg id="session" fieldErrors={fieldErrors} />
            </FG>
          </div>
        </div>
      </div>

      {/* Banking */}
      <div className="section-card">
        <div className="section-header">
          <div className="section-icon rose"><i className="fas fa-university"></i></div>
          <div><div className="section-title">Banking & Fee Information</div><div className="section-desc">Used on fee challans for parent payments</div></div>
        </div>
        <div className="helper-banner">
          <i className="fas fa-info-circle"></i>
          <span>These banking details will be displayed to parents on fee challans and payment receipts. Please ensure all information is accurate.</span>
        </div>
        <div className="form-grid form-grid-2">
          <FG label="Bank Name" id="bankName">
            <div className="input-wrapper">
              <i className="fas fa-university input-icon"></i>
              <input className="form-input has-icon" placeholder="e.g. Bank Islami Pakistan" value={schoolInfo.bankName}
                onChange={e => handleChange('bankName', e.target.value)} />
            </div>
          </FG>
          <FG label="Account Title" id="accountTitle">
            <div className="input-wrapper">
              <i className="fas fa-user input-icon"></i>
              <input className="form-input has-icon" placeholder="Account holder name" value={schoolInfo.accountTitle}
                onChange={e => handleChange('accountTitle', e.target.value)} />
            </div>
          </FG>
          <FG label="Account Number" id="accountNo" required>
            <div className="input-wrapper">
              <i className="fas fa-hashtag input-icon"></i>
              <input className={`form-input has-icon${fieldErrors.accountNo === 'error' ? ' error-field' : fieldErrors.accountNo === 'ok' ? ' success-field' : ''}`}
                placeholder="Bank account number" value={schoolInfo.accountNo}
                onChange={e => handleChange('accountNo', e.target.value)}
                onBlur={e => handleBlur('accountNo', e.target.value)} />
            </div>
            <FieldMsg id="accountNo" fieldErrors={fieldErrors} />
          </FG>
          <FG label="IBAN" id="iban" required>
            <div className="input-wrapper">
              <i className="fas fa-credit-card input-icon"></i>
              <input className={`form-input has-icon${fieldErrors.iban === 'error' ? ' error-field' : fieldErrors.iban === 'ok' ? ' success-field' : ''}`}
                placeholder="PKXX BANK 0000 0000 0000" value={schoolInfo.iban}
                onChange={e => handleChange('iban', e.target.value)}
                onBlur={e => handleBlur('iban', e.target.value)} />
            </div>
            <FieldMsg id="iban" fieldErrors={fieldErrors} />
          </FG>
          <FG label="Branch Name" id="branchName">
            <div className="input-wrapper">
              <i className="fas fa-map-marker-alt input-icon"></i>
              <input className="form-input has-icon" placeholder="e.g. Blue Area Branch" value={schoolInfo.branchName}
                onChange={e => handleChange('branchName', e.target.value)} />
            </div>
          </FG>
        </div>
      </div>

      {/* Save Bar */}
      <div className="save-bar">
        <div className="save-bar-left">
          <div className="autosave-dot"></div>
          <span>Draft auto-saved</span>
        </div>
        <div className="save-bar-right">
          <button className="btn btn-secondary btn-md" onClick={handleDraft} disabled={saving}>
            {saving ? <><i className="fas fa-spinner fa-spin"></i> Saving...</> : <><i className="fas fa-save"></i> Save Draft</>}
          </button>
          <button className="btn btn-primary btn-md" onClick={handleSave} disabled={saving}>
            {saving ? <><i className="fas fa-spinner fa-spin"></i> Saving...</> : <>Save & Continue <i className="fas fa-arrow-right"></i></>}
          </button>
        </div>
      </div>
    </div>
  );
}
